css:
.sl-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; background: #dccaa6; }
.sl-stage canvas { touch-action: none; cursor: grab; }
.sl-out { margin: 0; font-size: 21px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 10px 14px; min-height: 4.6em; }
.sl-facts { display: grid; grid-template-columns: auto 1fr; gap: 6px 14px; margin: 0; font-size: 21px; line-height: 1.45; }
.sl-facts dt { font-weight: 800; color: var(--accent); white-space: nowrap; }
.sl-facts dd { margin: 0; }
section.ex.u-done .sl-facts { display: none; }

